{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Weincluded randomised trials of people at risk of covid-19 that compared drugs, therapeutic doses of vitamins, or antibodies for prophylaxis against one another or against no prophylaxis (placebo or standard care, as defined by the researchers), with no restriction onlanguageofpublication. We included studies addressing people pre- or post-exposure to covid-19 and at low risk (e.g. unexposed community member) or high risk (e.g. member of the same household with one or more positive cases, contact of index case, healthcare worker or long term care resident) for covid-19.",
      "reason": "Specifies eligible study design (randomised trials) and participant/exposure characteristics (pre-/post-exposure; low- vs high-risk) and an eligibility comparison (prophylaxis vs no prophylaxis or vs other prophylaxis). However, it does not specify study settings or follow-up requirements, and does not clearly cover all study-characteristic components (e.g., question-framework elements and follow-up) as required."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "All trials were published in English. Almost all trials were registered (31, 97%) and evaluated prophylactic drugs against standard care or placebo (30, 94%). Of the 32 eligible randomised trials, 22 (69%) were published in peer reviewed journals and 10 (31%) only as preprint.",
      "reason": "Report characteristics are partially specified: language (English) and publication/dissemination status (peer-reviewed vs preprint) are provided. However, dissemination year and publication/report status beyond these categories (e.g., an explicit year range) are not reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "Fig 1 | Study selection",
      "reason": "The figure is referenced, and visible evidence indicates exclusion categories including \"Not a randomised trial\" and \"Randomised trial with no results\" (among others). But the retrieved evidence does not clearly distinguish exclusion because outcomes were not measured versus exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "Among the 27 randomised trials that reported covid-19 exposure status of participants, 18 evaluated prophylactic drugs in participants without documented exposure to covid-19 (pre-exposure) and seven evaluated prophylactic drugs in participants with documented exposure to covid-19 (post-exposure). Two randomised trials evaluated prophylactic drugs in both participants pre-exposure and post-exposure to covid-19.",
      "reason": "The retrieved evidence identifies groups used to classify study participants for analyses (pre-exposure vs post-exposure). However, it does not specify the groups used in each synthesis or explicitly link these groups to the comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence lists exclusions (e.g., exclusions in text_13 and reasons in the study selection figure), but it does not provide rationales for any notable restrictions on study eligibility."
    }
  ],
  "confidence": 58
}

